pacing:-.035em}h1 em{color:#f5b260;font-style:normal}.description{max-width:545px;margin:21px 0 0;color:#d2e1d5;font-size:15px;line-height:1.8}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:31px}.button{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:45px;padding:0 18px;border-radius:8px;font-size:12px;font-weight:700;transition:transform .2s}.button:hover{transform:translateY(-2px)}.primary{background:var(--gold);color:var(--ink)}.outline{border:1px solid #8aac9e;color:#fff}.panel{overflow:hidden;border:1px solid #ffffff2e;border-radius:17px;background:#ffffff0f;box-shadow:0 20px 50px #00271d45;backdrop-filter:blur(10px)}.panel-top,.panel-bottom{display:flex;align-items:center;gap:8px;padding:15px 19px;font-size:10px;font-weight:800;letter-spacing:.11em}.panel-top{border-bottom:1px solid #ffffff1f;color:#d4e7da}.dot{width:7px;height:7px;border-radius:50%;background:#f2b052;box-shadow:0 0 0 4px #f2b0522e}.map-art{position:relative;height:246px;overflow:hidden;background:linear-gradient(135deg,#245f51,#174b40)}.map-art:before,.map-art:after{position:absolute;inset:0;content:'';opacity:.24;background-image:linear-gradient(35deg,transparent 48%,#b3dac44d 49%,#b3dac44d 51%,transparent 52%);background-size:80px 58px;transform:rotate(-9deg) scale(1.2)}.map-art:after{opacity:.15;transform:rotate(92deg) scale(1.2)}.line{position:absolute;z-index:1;width:130%;height:75px;border:2px solid #c9e0b35c;border-radius:50%}.l1{top:30px;left:-55px;transform:rotate(18deg)}.l2{top:129px;right:-80px;transform:rotate(-20deg)}.l3{top:77px;left:-95px;transform:rotate(-28deg)}.pin{position:absolute;z-index:2;width:13px;height:13px;border:3px solid #fff4dc;border-radius:50% 50% 50% 0;background:var(--orange);transform:rotate(-45deg);box-shadow:0 3px 12px #361105a6}.p1{top:70px;left:28%}.p2{top:145px;right:25%}.p3{top:94px;right:43%}.placeholder{position:absolute;z-index:2;right:15px;bottom:15px;padding:7px 9px;border:1px solid #ffffff2e;border-radiu