order-radius:50%;color:#f0b25c;font-size:25px}.about h2{margin:0;font-size:25px;letter-spacing:-.02em}.about p{max-width:620px;margin:6px 0 0;color:#bdd3c4;font-size:11px;line-height:1.7}.text-link{color:#f6b45e;font-size:12px;font-weight:700;white-space:nowrap}.foot{background:var(--dark);color:#aec4b8}.foot .wrap{font-size:10px}.footer-brand b{color:#fff}.foot a{color:#d1e4d7;font-weight:600}@media(max-width:780px){.nav>a:not(.map-link){display:none}.hero-grid{grid-template-columns:1fr;gap:42px;padding:64px 0}.panel{max-width:470px;width:100%}.stats{grid-template-columns:repeat(2,1fr)}.news-grid{grid-template-columns:1fr;gap:28px}.about-grid{grid-template-columns:auto 1fr}.text-link{grid-column:2}.section-head{align-items:start;flex-direction:column;gap:12px}.section-head>p{max-width:500px}.foot .wrap{flex-wrap:wrap;padding:18px 0;gap:12px 20px}}@media(max-width:460px){.wrap{width:min(100% - 30px,1120px)}.head .wrap{min-height:67px}.brand small{display:none}.brand b{font-size:11px}.flame{width:34px;height:34px}.nav .map-link{padding:9px 10px;font-size:10px}h1{font-size:39px}.stats{grid-template-columns:1fr}.card{min-height:145px}.icon{margin-bottom:15px}.about-grid{gap:15px}.about h2{font-size:21px}}
